INSERT INTO instancias (idx, prem, hyp, batch_name, source_file) VALUES
  (3905, $$Incluso con la continua generosidad de los donantes, el museo tiene programas y operaciones que no reciben financiación todos los años.$$, $$Al museo le faltan 500 000 $ este año.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3906, $$Jerry Bepko, canciller de IUPUI, rindió homenaje a Carlos a través de estos comentarios.$$, $$Bepko honró a Carlos en su discurso de graduación.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3907, $$Jerry Bepko, canciller de IUPUI, rindió homenaje a Kent a través de estos comentarios.$$, $$Bepko honró a Kent.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3908, $$Jerry Bepko, canciller de IUPUI, rindió homenaje a Kent a través de estos comentarios.$$, $$Bepko nunca tuvo nada bueno que decir sobre Kent.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3909, $$Podemos seguir reforzando la educación de buenos abogados.$$, $$No hay forma de que podamos educar a los abogados, así que deberíamos dejar de intentarlo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3910, $$Podemos seguir reforzando la educación de buenos abogados.$$, $$Podemos educar a los abogados si podemos darles acceso a la biblioteca de derecho.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3911, $$Podemos seguir reforzando la educación de buenos abogados.$$, $$Podemos educar a los abogados, ¡estoy seguro de eso!$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3912, $$Es importante y esperamos que haga una contribución considerable al fondo de la Búsqueda de la Excelencia este año.$$, $$Este año el fondo Pursuit of Excellence está lleno de donaciones, por favor, considere donar a otro fondo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3913, $$Es importante y esperamos que haga una contribución considerable al fondo de la Búsqueda de la Excelencia este año.$$, $$Queremos que sepas lo mucho que la Búsqueda de la Excelencia necesita tus donaciones este año.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3914, $$Es importante y esperamos que haga una contribución considerable al fondo de la Búsqueda de la Excelencia este año.$$, $$Sin su contribución, el fondo Pursuit of Excellence ya no existirá.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3915, $$Puesto que nos volvemos independientes, por favor, ayúdanos a fortalecer la distinción de tu grado.$$, $$Nos estamos volviendo dependientes de los demás.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3916, $$Puesto que nos volvemos independientes, por favor, ayúdanos a fortalecer la distinción de tu grado.$$, $$Esperamos que nos ayudes cuando seamos independientes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3917, $$Puesto que nos volvemos independientes, por favor, ayúdanos a fortalecer la distinción de tu grado.$$, $$Usted recibió un título en biología molecular.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3918, $$Una encuesta reciente de Lou Harris indica que más del 66% de las líderes empresariales femeninas actuales tienen antecedentes de Girl Scouts.$$, $$Solo el 10 % de las mujeres líderes empresariales han estado en Scouts.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3919, $$Una encuesta reciente de Lou Harris indica que más del 66% de las líderes empresariales femeninas actuales tienen antecedentes de Girl Scouts.$$, $$Dos tercios de las mujeres líderes empresariales han sido Girl Scouts.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3920, $$Una encuesta reciente de Lou Harris indica que más del 66% de las líderes empresariales femeninas actuales tienen antecedentes de Girl Scouts.$$, $$Dos tercios de las mujeres líderes empresariales fueron niñas exploradoras durante al menos cinco años.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3921, $$Usted, junto con otros miembros afectuosos, estará ayudando en el esfuerzo por preservar y promover la orgullosa herencia de nuestro estado.$$, $$Se necesita ayuda para el estado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3922, $$Usted, junto con otros miembros afectuosos, estará ayudando en el esfuerzo por preservar y promover la orgullosa herencia de nuestro estado.$$, $$El estado lo está haciendo bien sin la ayuda de nadie.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3923, $$Usted, junto con otros miembros afectuosos, estará ayudando en el esfuerzo por preservar y promover la orgullosa herencia de nuestro estado.$$, $$El estado necesita que todos donen 20 $ para apoyar el patrimonio.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3924, $$Con su membresía podrá acudir a actividades solo para miembros y tendrá credenciales completas para todas las sesiones de congresos oficiales.$$, $$Ingresará en nuestros eventos exclusivos para miembros si paga la tarifa de membresía.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3925, $$Con su membresía podrá acudir a actividades solo para miembros y tendrá credenciales completas para todas las sesiones de congresos oficiales.$$, $$Ingresará a los eventos sólo para miembros que se realizan cada dos semanas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3926, $$Con su membresía podrá acudir a actividades solo para miembros y tendrá credenciales completas para todas las sesiones de congresos oficiales.$$, $$Aún tendrás que pagar para participar en todos los eventos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3927, $$El almuerzo de ex-alumnos de este año se celebrará el 23 de octubre de 1991, durante la reunión anual del AMRA Annual en Nashville, Tennessee.$$, $$La Reunión Anual de AMRA se realiza en Nashville todos los años.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3928, $$El almuerzo de alumnos de este año se celebrará el 23 de octubre de 1991, durante la reunión anual del AMRA en Nashville, Tennessee.$$, $$La reunión anual del AMRA se realizó en Nashville en 1991.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3929, $$El almuerzo de exalumnos de este año se celebrará el 23 de octubre de 1991, durante la reunión anual de AMRA en Nashville, Tennessee.$$, $$La reunión anual de AMRA se realizó en Texas en 1991.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3930, $$¿CUÁL ES EL DESAFÍO DE LAS PERSONAS MAYORES?$$, $$Hay un desafío para las personas mayores.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3931, $$¿CUÁL ES EL DESAFÍO PRINCIPAL?$$, $$Desafiamos a la gente mayor a caminar un kilómetro y medio por día.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3932, $$¿CUÁL ES EL DESAFÍO PRINCIPAL?$$, $$No tenemos ningún programa para personas mayores.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3933, $$Su sociedad humana no solo ofrece servicios sociales comunitarios efectivos a los animales y el pueblo, sino que también hace las funciones de perrera de la ciudad de Nashua.$$, $$La sociedad humana se preocupa por 1000 animales al año.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3934, $$Su sociedad humana no solo ofrece servicios sociales comunitarios efectivos a los animales y el pueblo, sino que también hace las funciones de perrera de la ciudad de Nashua.$$, $$La sociedad humana no funciona con animales en absoluto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3935, $$Su sociedad humana no solo ofrece servicios sociales comunitarios efectivos a los animales y el pueblo, sino que también hace las funciones de perrera de la ciudad de Nashua.$$, $$La sociedad humana es el refugio de animales de Nashua.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3936, $$Las dificultades de la estructura anatómica de los elefantes hicieron que lo que se considera un procedimiento común entre animales domésticos sea extremadamente problemático.$$, $$Los elefantes son como cualquier otro animal.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3937, $$Las dificultades de la estructura anatómica de los elefantes hacen que lo que se considera un procedimiento común entre animales domésticos sea extremadamente problemático.$$, $$Es difícil de utilizar con los elefantes porque pesan mucho más que otros animales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3938, $$Las dificultades de la estructura anatómica de los elefantes hacen que lo que se considera un procedimiento común entre animales domésticos sea extremadamente problemático.$$, $$Es difícil operar a elefantes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3939, $$Es posible que no hayamos tenido todo lo que queríamos o que habíamos visto que otras personas tenían, pero se aseguró de que tuviéramos las cosas necesarias que necesitábamos.$$, $$Teníamos todo lo que podíamos soñar.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3940, $$Es posible que no hayamos tenido todo lo que queríamos o que habíamos visto que otras personas tenían, pero se aseguró de que tuviéramos las cosas necesarias que necesitábamos.$$, $$Teníamos todo lo que realmente necesitábamos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3941, $$Es posible que no hayamos tenido todo lo que queríamos o que habíamos visto que otras personas tenían, pero se aseguró de que tuviéramos las cosas necesarias que necesitábamos.$$, $$Tuvimos comida y refugio, pero nada más en realidad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3942, $$He estado afiliado al IRT durante 17 años.$$, $$No tengo nada que ver con el IRT.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3943, $$He estado afiliado al IRT durante 17 años.$$, $$He trabajado en recaudación de fondos para el IRT durante más de una década.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3944, $$He estado afiliado al IRT durante 17 años.$$, $$He trabajado con IRT durante mucho tiempo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3945, $$Diálogo con representantes de la ciudad y otras organizaciones cívicas y comunitarias con respecto al desarrollo del arte del IMA.$$, $$El IMA funciona de forma independiente todos los días.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3946, $$Diálogo con representantes de la ciudad y otras organizaciones cívicas y comunitarias con respecto al desarrollo del arte del IMA.$$, $$El IMA trabaja con otras organizaciones, ya que todas ellas dependen de la financiación compartida.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3947, $$Diálogo con representantes de la ciudad y otras organizaciones cívicas y comunitarias con respecto al desarrollo del arte del IMA.$$, $$El IMA trabaja con otras organizaciones del área.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3948, $$Si bien las cifras son impresionantes, las becas a menudo son críticas para reclutar a los mejores estudiantes con necesidades financieras.$$, $$Los mejores estudiantes con necesidades financieras se benefician de becas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3949, $$Si bien las cifras son impresionantes, las becas a menudo son críticas para reclutar a los mejores estudiantes con necesidades financieras.$$, $$Hay 50 becas disponibles para los 50 mejores estudiantes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3950, $$Si bien las cifras son impresionantes, las becas a menudo son críticas para reclutar a los mejores estudiantes con necesidades financieras.$$, $$No otorgamos becas ni ayuda financiera a estudiantes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3951, $$Mi intuición, por supuesto, tiene una base muy específica: sos una persona que se preocupa, según demostraste con tu donación de administración anual a tu parroquia.$$, $$Puedo decir que sos un verdadero idiota.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3952, $$Mi intuición, por supuesto, tiene una base muy específica: sos una persona que se preocupa, según has demostrado con tu donación de administración anual a tu parroquia.$$, $$Siento que sos una buena persona y cariñosa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3953, $$Mi intuición, por supuesto, tiene una base muy específica: sos una persona que se preocupa, según demostraste con tu donación de administración anual a tu parroquia.$$, $$Su donación de $2000 demuestra que es usted una buena persona.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3954, $$Y ella siempre estuvo ahí para nosotros$$, $$Ella nos dio toda la plata que necesitábamos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3955, $$Y ella siempre estuvo ahí para nosotros$$, $$¡Ella nunca nos apoyó en nada!$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3956, $$Y ella siempre estuvo ahí para nosotros$$, $$Ella fue un buen apoyo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3957, $$Mi sueño es que todos los estadounidenses formen parte de la familia olímpica, así que, por favor, den todo lo que puedan.$$, $$Creo que todos los estadounidenses son atletas natos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3958, $$Mi sueño es que todos los estadounidenses formen parte de la familia olímpica, así que, por favor, den todo lo que puedan.$$, $$Sólo quiero ver a las mujeres estadounidenses convertirse en olímpicas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3959, $$Mi sueño es que todos los estadounidenses formen parte de la familia olímpica, así que, por favor, den todo lo que puedan.$$, $$Quiero ver a los estadounidenses unirse a la familia olímpica.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3960, $$Estos asientos abiertos, Washington, Colorado y Dakota del Norte, junto con la salida del longevo demócrata, Alan Dixon, han aumentado en gran medida nuestras opciones de victoria.$$, $$Alan Dixon es un político demócrata.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3961, $$Estos asientos abiertos, Washington, Colorado y Dakota del Norte, junto con la salida del longevo demócrata, Alan Dixon, han aumentado en gran medida nuestras opciones de victoria.$$, $$Alan Dixon es un republicano muy duro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3962, $$Estos asientos abiertos, Washington, Colorado y Dakota del Norte, junto con la salida del longevo demócrata, Alan Dixon, han aumentado en gran medida nuestras opciones de victoria.$$, $$Alan Dixon era un senador estatal.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3963, $$En 1990, el Programa estableció el Premio de Servicio Distinguido Elton T. Ridley.$$, $$El premio no se inició hasta 2002.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3964, $$En 1990, el Programa estableció el Premio de Servicio Distinguido Elton T. Ridley.$$, $$Comenzaron el Premio en 1990 porque obtuvieron una gran subvención.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3965, $$En 1990, el Programa estableció el Premio de Servicio Distinguido Elton T. Ridley.$$, $$Comenzaron el premio en 1990.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3966, $$Además, los residentes de Indiana pueden recibir beneficios fiscales mediante el crédito fiscal de Indiana, que se aplica directamente al resultado final de la declaración de impuestos estatal.$$, $$Indiana no ofrece créditos fiscales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3967, $$Además, los residentes de Indiana pueden recibir beneficios fiscales mediante el crédito fiscal de Indiana, que se aplica directamente al resultado final de la declaración de impuestos estatal.$$, $$Los residentes de Indiana obtienen un crédito fiscal del 50% si donan al teatro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3968, $$Además, los residentes de Indiana pueden recibir beneficios fiscales mediante el crédito fiscal de Indiana, que se aplica directamente al resultado final de la declaración de impuestos estatal.$$, $$Los residentes en Indiana obtienen beneficios fiscales del estado de Indiana.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3969, $$Después de un espectáculo, una pareja joven vino al escenario para saludar.$$, $$Había una pareja joven en el espectáculo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3970, $$Después de un espectáculo, una pareja joven vino al escenario para saludar.$$, $$Una joven pareja fue a su primera actuación.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3971, $$Después de un espectáculo, una pareja joven vino al escenario para saludar.$$, $$Nadie en el espectáculo tenía menos de 80 años.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3972, $$Estamos pidiendo a los graduados una donación de 1000 $.$$, $$Estamos recaudando fondos de los graduados.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3973, $$Estamos pidiendo a los graduados una donación de 1000 $.$$, $$Estamos recaudando fondos para llegar a nuestra meta de 100.000 $.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3974, $$Estamos pidiendo a los graduados una donación de 1000 $.$$, $$Solo nos dirigimos a estudiantes actuales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3975, $$.. Hacé que nuestra sociedad sea mejor.$$, $$Nuestra sociedad no necesita ayuda.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3976, $$.. Hacé que nuestra sociedad sea mejor.$$, $$Por favor ayudá a mejorar nuestra sociedad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3977, $$.. Hacé que nuestra sociedad sea mejor.$$, $$Esperamos que haga de nuestra sociedad un lugar libre de crímenes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3981, $$Por consiguiente, sé que te esforzás mucho para ser compasivo y cariñoso con otros.$$, $$Ya sé que te importa mucho la gente que te rodea.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3982, $$Por consiguiente, sé que te esforzás mucho para ser compasivo y cariñoso con otros.$$, $$Sé que no te importan las personas en absoluto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3984, $$Los amigos operan en dos niveles: los Citywide Friends y los Branch Friends, y podés estar activo en uno o en ambos niveles.$$, $$El nivel de amigos depende de cuánto hayas donado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3985, $$Los amigos operan en dos niveles: los Citywide Friends y los Branch Friends, y podés estar activo en uno o en ambos niveles.$$, $$Hay dos niveles de Amigos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3986, $$Los amigos operan en dos niveles: los Citywide Friends y los Branch Friends, y podés estar activo en uno o en ambos niveles.$$, $$No separamos el nivel de amigos, todos son iguales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3987, $$Esto es extremadamente importante para la supervivencia a largo plazo de los elefantes tanto bajo cuidados de los humanos, y también en entornos salvajes.$$, $$Si nos das plata, podemos proteger a todos los elefantes de África.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3990, $$Por favor, dá ahora para que podamos seguir dándote a vos, a tus amigos y a tus vecinos.$$, $$Si donás ahora, nos ayudará mucho.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3991, $$Por favor, dá ahora para que podamos seguir dándote a vos, a tus amigos y a tus vecinos.$$, $$No necesitamos más donaciones.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3992, $$Por favor, dá ahora para que podamos seguir dándote a vos, a tus amigos y a tus vecinos.$$, $$Dejaremos de recaudar fondos si nos da 1000$ ahora.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (3993, $$La ceremonia de graduación de 1991 renueva los recuerdos de los días de estudiante en la Universidad de Indiana.$$, $$La ceremonia de graduación de 1991 fue cancelada por condiciones climáticas desastrosas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
