  (5556, $$Cuando la sociedad civil hace oídos sordos, las ideas locas pierden su ventaja.$$, $$Las ideas locas son menos agudas cuando son ignoradas por la sociedad civil.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
  (5557, $$Cuando la sociedad civil hace oídos sordos, las ideas locas pierden su ventaja.$$, $$Las ideas locas se vuelven más populares entre la sociedad civil cuando son ignoradas por la sociedad civil.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_03.jsonl$$),
